#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>
#include <cmath>

class mcf_graph_int_cost {
public:
    struct edge {
        int from_;
        int to_;
        int cap;
        int flow;
        int cost;
        edge(int from_, int to_, int cap, int flow, int cost) 
            : from_(from_), to_(to_), cap(cap), flow(flow), cost(cost) {}
    };

    struct _edge {
        int to;
        int rev;
        int cap;
        int cost;
        _edge(int to, int rev, int cap, int cost) 
            : to(to), rev(rev), cap(cap), cost(cost) {}
    };

    int n;
    std::vector<std::pair<int, int>> pos;
    std::vector<std::vector<_edge>> g;

    mcf_graph_int_cost(int n) : n(n), pos(), g(n) {}

    int add_edge(int from_, int to, int cap, int cost) {
        int m = pos.size();
        pos.push_back({from_, (int)g[from_].size()});
        g[from_].push_back(_edge(to, (int)g[to].size(), cap, cost));
        g[to].push_back(_edge(from_, (int)g[from_].size() - 1, 0, -cost));
        return m;
    }

    edge get_edge(int i) {
        _edge& _e = g[pos[i].first][pos[i].second];
        _edge& _re = g[_e.to][_e.rev];
        return edge(pos[i].first, _e.to, _e.cap + _re.cap, _re.cap, _e.cost);
    }

    std::vector<edge> edges() {
        std::vector<edge> ret;
        for (int i = 0; i < pos.size(); i++) {
            _edge& _e = g[pos[i].first][pos[i].second];
            _edge& _re = g[_e.to][_e.rev];
            ret.push_back(edge(pos[i].first, _e.to, _e.cap + _re.cap, _re.cap, _e.cost));
        }
        return ret;
    }

    std::vector<int> dist;
    std::vector<int> pv;
    std::vector<int> pe;
    std::vector<bool> vis;
    std::vector<int> dual;

    bool _dual_ref(int s, int t) {
        dist.assign(n, 4294967295);
        pv.assign(n, -1);
        pe.assign(n, -1);
        vis.assign(n, false);

        // Using priority_queue as min-heap
        auto cmp = [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
            return a.first > b.first;
        };
        std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, decltype(cmp)> que(cmp);

        dist[s] = 0;
        que.push({0, s});

        while (!que.empty()) {
            int v = que.top().second;
            que.pop();
            if (vis[v]) continue;
            vis[v] = true;
            if (v == t) break;

            for (int i = 0; i < (int)g[v].size(); i++) {
                _edge& e = g[v][i];
                if (vis[e.to] || e.cap == 0) continue;
                int cost = e.cost - dual[e.to] + dual[v];
                if (dist[e.to] > dist[v] + cost) {
                    dist[e.to] = dist[v] + cost;
                    pv[e.to] = v;
                    pe[e.to] = i;
                    que.push({dist[e.to], e.to});
                }
            }
        }

        if (!vis[t]) return false;

        for (int v = 0; v < n; v++) {
            if (!vis[v]) continue;
            dual[v] -= dist[t] - dist[v];
        }

        return true;
    }

    std::vector<std::pair<int, int>> slope(int s, int t, int flow_limit = 4294967295) {
        dual.assign(n, 0);
        dist.assign(n, 4294967295);
        pv.assign(n, -1);
        pe.assign(n, -1);
        vis.assign(n, false);

        int flow = 0;
        int cost = 0;
        int prev_cost = -1;
        std::vector<std::pair<int, int>> result;
        result.push_back({flow, cost});

        while (flow < flow_limit) {
            if (!_dual_ref(s, t)) break;

            int c = flow_limit - flow;
            int v = t;
            while (v != s) {
                c = std::min(c, g[pv[v]][pe[v]].cap);
                v = pv[v];
            }

            v = t;
            while (v != s) {
                _edge& e = g[pv[v]][pe[v]];
                e.cap -= c;
                g[v][e.rev].cap += c;
                v = pv[v];
            }

            int d = -dual[s];
            flow += c;
            cost += c * d;

            if (prev_cost == d) {
                result.pop_back();
            }
            result.push_back({flow, cost});
            prev_cost = cost;
        }
        return result;
    }

    std::pair<int, int> flow(int s, int t, int flow_limit = 4294967295) {
        auto res = slope(s, t, flow_limit);
        return res.back();
    }
};

int main() {
    int n;
    std::cin >> n;
    int a1, a2, a3;
    std::cin >> a1 >> a2 >> a3;
    int b1, b2, b3;
    std::cin >> b1 >> b2 >> b3;

    mcf_graph_int_cost g(8);
    g.add_edge(0, 1, a1, 0);
    g.add_edge(0, 2, a2, 0);
    g.add_edge(0, 3, a3, 0);
    g.add_edge(4, 7, b1, 0);
    g.add_edge(5, 7, b2, 0);
    g.add_edge(6, 7, b3, 0);

    for (int i = 1; i <= 3; i++) {
        for (int j = 4; j <= 6; j++) {
            int cost = ((j - i) % 3 == 1) ? 1 : 0;
            g.add_edge(i, j, INT_MAX, cost);
        }
    }

    auto res = g.flow(0, 7);
    int ans1 = res.second;

    int ans2 = std::min(a1, b2) + std::min(a2, b3) + std::min(a3, b1);

    std::cout << ans1 << " " << ans2 << std::endl;

    return 0;
}

