long long give(vector<vector<long long>>& l1, vector<vector<long long>>& l2) {
    long long ans = 0;
    vector<vector<long long>> a = l1;
    vector<vector<long long>> b = l2;

    long long i1 = 0, i2 = 0;

    while (i1 < a.size() && i2 < b.size()) {
        long long curr1_count = a[i1][0];
        long long curr1_type = a[i1][1];
        long long curr2_count = b[i2][0];
        long long curr2_type = b[i2][1];

        long long common = min(curr1_count, curr2_count);
        ans += max(0LL, common * match(curr1_type, curr2_type));

        if (curr1_count < curr2_count) {
            b[i2][0] -= curr1_count;
            i1++;
        } else if (curr1_count > curr2_count) {
            a[i1][0] -= curr2_count;
            i2++;
        } else {
            i1++;
            i2++;
        }
    }

    return ans;
}

long long maximum(long long rock1, long long sci1, long long paper1, long long rock2, long long sci2, long long paper2) {
    long long ans = min(rock1, sci2) + min(sci1, paper2) + min(paper1, rock2);
    return ans;
}

long long minimum(long long rock1, long long sci1, long long paper1, long long rock2, long long sci2, long long paper2) {
    vector<vector<long long>> l = {{rock1, 1}, {sci1, 2}, {paper1, 3}};
    vector<vector<vector<long long>>> l1;

    sort(l.begin(), l.end());
    do {
        l1.push_back(l);
    } while (next_permutation(l.begin(), l.end()));

    vector<vector<long long>> l2_vec = {{rock2, 1}, {sci2, 2}, {paper2, 3}};
    vector<vector<vector<long long>>> l2_perms;

    sort(l2_vec.begin(), l2_vec.end());
    do {
        l2_perms.push_back(l2_vec);
    } while (next_permutation(l2_vec.begin(), l2_vec.end()));

    long long ans = LLONG_MAX;
    for (auto& perm1 : l1) {
        for (auto& perm2 : l2_perms) {
            vector<vector<long long>> mylist1 = perm1;
            vector<vector<long long>> mylist2 = perm2;
            long long res = give(mylist1, mylist2);
            if (res < ans) ans = res;
        }
    }

    return ans;
}

