int getWonMaxFast(vector<int> inputA, vector<int> inputB) {
    vector<int> wins(3, 0);
    for (int i = 0; i < 3; i++) {
        int good = (i + 1) % 3;
        wins[i] = min(inputA[i], inputB[good]);
        inputA[i] -= wins[i];
        inputB[good] -= wins[i];
    }
    return accumulate(wins.begin(), wins.end(), 0);
}

int getLostMaxFast(vector<int> inputA, vector<int> inputB) {
    vector<vector<int>> waysToLose = {{0, 2}, {1, 0}, {2, 1}, {0, 0}, {1, 1}, {2, 2}};

    vector<vector<vector<int>>> allWaysToLosePermutations;

    sort(waysToLose.begin(), waysToLose.end());
    do {
        allWaysToLosePermutations.push_back(waysToLose);
    } while (next_permutation(waysToLose.begin(), waysToLose.end()));

    int maxLost = 0;

    for (const auto& permutation : allWaysToLosePermutations) {
        vector<int> losts(3, 0);
        vector<int> inputACopy = inputA;
        vector<int> inputBCopy = inputB;

        for (const auto& wayToLose : permutation) {
            int lost_add = min(inputACopy[wayToLose[0]], inputBCopy[wayToLose[1]]);
            inputACopy[wayToLose[0]] -= lost_add;
            inputBCopy[wayToLose[1]] -= lost_add;
            losts[wayToLose[0]] += lost_add;
        }

        int lostSum = accumulate(losts.begin(), losts.end(), 0);

        if (lostSum > maxLost) {
            maxLost = lostSum;
        }
    }

    return maxLost;
}

int main() {
    int n;
    cin >> n;

    vector<int> inputA(3);
    vector<int> inputB(3);

    for (int i = 0; i < 3; i++) {
        cin >> inputA[i];
    }

    for (int i = 0; i < 3; i++) {
        cin >> inputB[i];
    }

    vector<int> inputA2 = inputA;
    vector<int> inputB2 = inputB;

    cout << n - getLostMaxFast(inputA2, inputB2) << " " << getWonMaxFast(inputA, inputB) << endl;

    return 0;
}

