void solve(int round, std::vector<int>& firstperson, std::vector<int>& secondperson) {
    // find max win
    int win = 0;
    secondperson.push_back(secondperson[0]);
    for (int i = 0; i < static_cast<int>(firstperson.size()); ++i) {
        int findless;
        if (firstperson[i] <= secondperson[i + 1]) {
            findless = firstperson[i];
        } else {
            findless = secondperson[i + 1];
        }
        win += findless;
    }
    secondperson.erase(secondperson.begin() + 3);

    // find min win
    secondperson.insert(secondperson.begin(), secondperson[2]);

    for (int i = 0; i < static_cast<int>(firstperson.size()); ++i) {
        if (firstperson[i] > 0) {
            int diff = std::min(firstperson[i], secondperson[i]);
            firstperson[i] -= diff;
            secondperson[i] -= diff;
            if (firstperson[i] > 0) {
                diff = std::min(firstperson[i], secondperson[i + 1]);
                firstperson[i] -= diff;
                secondperson[i + 1] -= diff;
            }
        }
    }

    std::cout << (firstperson[0] + firstperson[1] + firstperson[2]) << " " << win << std::endl;
}

int main() {
    int round;
    std::cin >> round;

    std::string line1, line2;
    std::cin >> line1 >> line2 >> line2; // This line is to consume the rest of the input line
    std::cin.ignore();
    std::getline(std::cin, line1);
