    std::cin >> N >> MOD;

    std::vector<long long> DP(N, 0);
    DP[0] = 1;

    std::vector<long long> Cum(N + 1, 0);
    Cum[1] = 1;

    for (int i1 = 1; i1 < N; i1++) {
        int i2 = N - i1;
        long long Value = Cum[i1];

        for (int j = 2; j <= N; j++) {
            if (i2 * j > N) break;
            int lower = std::max(0, N - i2 * j - j + 1);
            int upper = N - i2 * j + 1;
            Value += Cum[upper] - Cum[lower];
            Value %= MOD;
        }

        Cum[i1 + 1] += Cum[i1] + Value;
        Cum[i1 + 1] %= MOD;
        DP[i1] = Value;
    }

    std::cout << DP[N - 1] << std::endl;

    return 0;
}

