#include <iostream>
#include <vector>
#include <map>
#include <cmath>

using namespace std;

vector<int> primes;

void generate_primes() {
    for (int p = 2; p < 6000; p++) {
        bool is_prime = true;
        for (int p2 : primes) {
            if (p2 * p2 > p) {
                break;
            }
            if (p % p2 == 0) {
                is_prime = false;
                break;
            }
        }
        if (is_prime) {
            primes.push_back(p);
        }
    }
}

map<int, int> factor(int n) {
    map<int, int> d;
    for (int p : primes) {
        if (p * p > n) {
            break;
        }
        if (n % p == 0) {
            int c = 0;
            while (n % p == 0) {
                n = n / p;
                c++;
            }
            d[p] = c;
        }
    }
    if (n > 1) {
        d[n] = 1;
    }
    return d;
}

vector<int> factors(int n) {
    map<int, int> d = factor(n);
    vector<int> answer;
    answer.push_back(1);

    for (auto& entry : d) {
        int p = entry.first;
        int exp = entry.second;
        vector<int> a2;

        for (int x : answer) {
            long long power = 1;
            for (int i = 0; i <= exp; i++) {
                a2.push_back(x * power);
                power *= p;
            }
        }
        answer = a2;
    }
    return answer;
}

int process(int n, int m) {
    map<int, int> f_dict;
    f_dict[0] = 0;
    f_dict[1] = 1;
    f_dict[2] = 2;

    for (int i = 3; i <= n; i++) {
        f_dict[i] = (2 * f_dict[i-1]) % m;

        vector<int> facs = factors(i);
        for (int x : facs) {
            if (2 <= x && x <= i) {
                f_dict[i] = (f_dict[i] + f_dict[i/x] - f_dict[(i-1)/x]) % m;
                if (f_dict[i] < 0) {
                    f_dict[i] += m;
                }
            }
        }
        f_dict[i] = f_dict[i] % m;
    }
    return f_dict[n];
}

int main() {
    generate_primes();

    int n, m;
    cin >> n >> m;

    cout << process(n, m) << endl;

    return 0;
}

