using namespace std;

const long long M = 1000000007;

long long modPow(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

void process() {
    int P, K;
    cin >> P >> K;

    vector<int> k(P);
    for (int x = 0; x < P; x++) {
        k[x] = (K * x) % P;
    }

    if (K == 0) {
        cout << modPow(P, P - 1, M) << endl;
        return;
    }
    if (K == 1) {
        cout << modPow(P, P, M) << endl;
        return;
    }

    vector<int> f(P, 0);
    vector<long long> c(P, 0);
    long long ans = 1;

    for (int i = 0; i < P; i++) {
        if (f[i]) continue;

        int cnt = 1;
        int u = i;
        f[u] = 1;
        while (!f[k[u]]) {
            u = k[u];
            f[u] = 1;
            cnt++;
        }

        if (cnt < P) {
            c[cnt]++;
        }
    }

    for (int i = 2; i < P; i++) {
        if (c[i] != 0) {
            long long cnt = (long long)i * c[i] + 1;
            ans = (ans * modPow(cnt, c[i], M)) % M;
        }
    }

    cout << ans << endl;
}

int main() {
    int T = 1;
    while (T--) {
        process();
    }
    return 0;
}

