// Fast I/O implementation
class FastIO {
private:
    char buf[8192];
    int bufPos;
    bool bufValid;
    FILE* file;

public:
    FastIO(FILE* f) : file(f), bufPos(0), bufValid(false) {}

    int readChar() {
        if (bufPos >= 8192 || !bufValid) {
            bufValid = true;
            bufPos = 0;
            size_t bytesRead = fread(buf, 1, 8192, file);
            if (bytesRead == 0) return EOF;
        }
        return buf[bufPos++];
    }

    char readCharNoSpace() {
        int c;
        do {
            c = readChar();
        } while (c <= 32 && c != EOF);
        return (char)c;
    }

    long long readLong() {
        long long x = 0;
        int c;
        bool neg = false;
        while ((c = readChar()) <= 32 && c != EOF);
        if (c == '-') {
            neg = true;
            c = readChar();
        }
        do {
            x = x * 10 + (c - '0');
            c = readChar();
        } while (c >= '0' && c <= '9');
        return neg ? -x : x;
    }

    string readString() {
        string s = "";
        int c;
        while ((c = readChar()) > 32) {
            s += (char)c;
        }
        return s;
    }
};

