        sl[i] = sl[i-1] + (1LL << i);
    }

    long long h, n;
    cin >> h >> n;

    vector<long long> nl;
    n += sl[h-1];
    long long tn = n;
    nl.push_back(tn);
    while (tn != 1) {
        tn = tn / 2;
        nl.push_back(tn);
    }

    long long ans = 0;
    long long cn = 1;
    bool cp = false;

    while (cn != n) {
        vector<long long> tnl;
        for (int i = 0; i < h; i++) {
            tnl.push_back(cn);
            if (cp == false) {
                cn = cn * 2;
            } else {
                cn = cn * 2 + 1;
            }
            cp = !cp;
        }
        if (cn == n) {
            ans += h;
            break;
        }

        tnl.push_back(cn);
        // Reverse tnl
        for (int i = 0; i < tnl.size() / 2; i++) {
            long long temp = tnl[i];
            tnl[i] = tnl[tnl.size() - 1 - i];
            tnl[tnl.size() - 1 - i] = temp;
        }

        for (int i = 1; i <= h; i++) {
            if (nl[i] == tnl[i]) {
