    if (pos == std::string::npos || pos + 2 > str.length()) {
        return str;
    }
    return str.substr(0, pos) + "@" + str.substr(pos + 2);
}

std::string process_string(const std::string& s) {
    std::string result = s;

    if (s.substr(0, 3) == "dot" || s.substr(0, 2) == "at" || 
        s.substr(s.length() - 2) == "at" || s.substr(s.length() - 3) == "dot") {

        if (s.substr(0, 3) == "dot") {
            std::string t = s.substr(3);
            std::vector<std::string> parts;
            size_t start = 0;
            size_t end = t.find("dot");
            while (end != std::string::npos) {
                parts.push_back(t.substr(start, end - start));
                start = end + 3;
                end = t.find("dot", start);
            }
            parts.push_back(t.substr(start));

            std::string l = "";
            for (size_t i = 0; i < parts.size(); ++i) {
                if (i > 0) l += ".";
                l += parts[i];
            }

            size_t b = l.find("at");
            std::string o = replace_at(l, b);
            std::string q = "dot" + o;

            if (!q.empty() && q.back() == '.') {
                std::string a = q.substr(0, q.length() - 1);
                result = a + "dot";
            } else if (!q.empty() && q.back() == '@') {
                std::string a = q.substr(0, q.length() - 1);
                result = a + "at";
            } else {
                result = q;
            }
        }

        if (s.substr(0, 2) == "at") {
            std::string t = s.substr(2);
            std::vector<std::string> parts;
            size_t start = 0;
