            for (size_t i = 0; i < parts.size(); ++i) {
                if (i > 0) l += ".";
                l += parts[i];
            }

            size_t b = l.find("at");
            std::string o = replace_at(l, b);
            std::string q = "at" + o;

            if (!q.empty() && q.back() == '.') {
                std::string a = q.substr(0, q.length() - 1);
                result = a + "dot";
            } else if (!q.empty() && q.back() == '@') {
                std::string a = q.substr(0, q.length() - 1);
                result = a + "at";
            } else {
                result = q;
            }
        }

        if (s.length() >= 3 && s.substr(s.length() - 3) == "dot" && 
            s.substr(0, 3) != "dot" && s.substr(0, 2) != "at") {
            std::string t = s.substr(0, s.length() - 3);
            std::vector<std::string> parts;
            size_t start = 0;
            size_t end = t.find("dot");
            while (end != std::string::npos) {
                parts.push_back(t.substr(start, end - start));
                start = end + 3;
                end = t.find("dot", start);
            }
            parts.push_back(t.substr(start));

            std::string l = "";
            for (size_t i = 0; i < parts.size(); ++i) {
                if (i > 0) l += ".";
                l += parts[i];
            }

            size_t b = l.find("at");
            std::string q = replace_at(l, b);
            result = q + "dot";
        }

        if (s.length() >= 2 && s.substr(s.length() - 2) == "at" && 
            s.substr(0, 3) != "dot" && s.substr(0, 2) != "at") {
            std::string t = s.substr(0, s.length() - 2);
            std::vector<std::string> parts;
            size_t start = 0;
