            parts.push_back(t.substr(start));

            std::string l = "";
            for (size_t i = 0; i < parts.size(); ++i) {
                if (i > 0) l += ".";
                l += parts[i];
            }

            size_t b = l.find("at");
            std::string q = replace_at(l, b);
            result = q + "at";
        }

    } else {
        std::vector<std::string> parts;
        size_t start = 0;
        size_t end = s.find("dot");
