#include <map>
#include <algorithm>
using namespace std;

int mod;

map<int, int> memo[101][2];

int invnum(const vector<int>& seq) {
    int N = seq.size();
    int res = 0;
    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            if (seq[i] > seq[j]) {
                res++;
            }
        }
    }
    return res;
}

int solve(int N, int k, bool flag) {
    if (memo[N][flag].count(k)) {
        return memo[N][flag][k];
    }

    if (N == 1) {
        int res = -1;
        if (flag) {
            res = 0;
        } else {
            if (k < 0) {
                res = 1;
            } else {
                res = 0;
            }
        }
        memo[N][flag][k] = res;
        return res;
    }

    int invnum_INF = (N * (N - 1)) / 2;
    if (k < -invnum_INF - 1) {
        int res = solve(N, -invnum_INF - 1, flag);
        memo[N][flag][k] = res;
        return res;
    }
    if (k >= invnum_INF) {
        memo[N][flag][k] = 0;
        return 0;
    }

    int res = 0;

    for (int delta = -N + 1; delta < N; delta++) {
        if (flag && (delta > 0)) {
            continue;
        }
        int wt = min(N - delta, delta + N);
        res = (res + 1LL * solve(N - 1, k - delta, (delta == 0) && flag) * wt) % mod;
    }

    memo[N][flag][k] = res % mod;
    return res % mod;
}

int main() {
    int n;
    cin >> n >> mod;

    int ans = solve(n, 0, true) % mod;
    cout << ans << endl;

    return 0;
}

