    ll t0 = 0, t1 = 1;
    while (r1 != 0) {
        ll q = r0 / r1;
        ll tmp = r0;
        r0 = r1;
        r1 = tmp - q * r1;
        tmp = s0;
        s0 = s1;
        s1 = tmp - q * s1;
        tmp = t0;
        t0 = t1;
