}

vector<ll> tf(ll n, ll M) {
    vector<ll> C(n + 1, 0);
    C[n] = 1;
    for (ll k = n - 1; k >= 0; --k) {
        C[k] = (C[k + 1] * (k + 1)) % M;
        if (C[k] == 0) break;
    }
    return C;
}

ll app(ll n, ll M) {
    vector<vector<vector<ll>>> K;
    K.push_back(vector<vector<ll>>(1, vector<ll>(1, 1)));

    for (ll i = 0; i < n - 1; ++i) {
        vector<vector<ll>>& Ki = K[i];
        ll ni = Ki.size();
        vector<vector<ll>> Ki_(ni + i + 1, vector<ll>(i + 2, 0));
        K.push_back(Ki_);

        for (ll j = 0; j < ni; ++j) {
            for (ll k = 0; k < Ki[j].size(); ++k) {
                ll v = Ki[j][k];
                for (ll h = 0; h < i + 1; ++h) {
                    Ki_[j + h][k] += v;
                    Ki_[j + h][k] %= M;
                }
                Ki_[j + i + 1][i + 1] += v;
                Ki_[j + i + 1][i + 1] %= M;
            }
        }
    }

    vector<ll> C = tf(n, M);
    ll s = 0;

    for (ll i = 1; i < n; ++i) {
        vector<vector<ll>>& Ki = K[i];
        ll ni = Ki.size();
        ll mi = Ki[0].size();
        vector<vector<ll>> Si(ni, vector<ll>(mi, 0));

        for (ll j = 0; j < ni; ++j) {
            Si[j][mi - 1] = Ki[j][mi - 1];
            for (ll k = mi - 2; k >= 0; --k) {
