            for (long long d = -i + 1; d < i; d++) {
                if (x + d >= 0 && x + d < (long long)dp[i].size()) {
                    dp[i][x + d] = (dp[i][x + d] + dp[i - 1][x] * (i - abs(d))) % mod;
