using namespace std;

long long t(int n, int h, vector<vector<long long>>& dp) {
    if (dp[n][h] == -1) {
        long long sum_val = 0;
        for (int m = 1; m <= n; m++) {
            long long inner_sum1 = 0;
            for (int i = 0; i < h; i++) {
                inner_sum1 += t(n - m, i, dp);
            }

            long long inner_sum2 = 0;
            for (int i = 0; i < h - 1; i++) {
                inner_sum2 += t(m - 1, i, dp);
            }

            sum_val += t(m - 1, h - 1, dp) * inner_sum1 + t(n - m, h - 1, dp) * inner_sum2;
        }
        dp[n][h] = sum_val;
    }
    return dp[n][h];
}

long long fill(int i, int j) {
    if (i == 0 && j == 0) {
        return 1;
    }
    if (i == 0 || j == 0) {
        return 0;
    }
    return -1;
}

