long long searchall(int lo, int hi) {
    if (lo == hi) {
        return 1;
    }
    if (all.find(make_pair(lo, hi)) != all.end()) {
        return all[make_pair(lo, hi)];
    }
    all[make_pair(lo, hi)] = 0;
    all[make_pair(lo, hi)] += searchall(lo + 1, hi);
    all[make_pair(lo, hi)] += searchall(lo, hi - 1);
    for (int i = lo + 1; i < hi; i++) {
        all[make_pair(lo, hi)] += searchall(lo, i - 1) * searchall(i + 1, hi);
    }
    return all[make_pair(lo, hi)];
}

long long searchlimit(int lo, int hi, int depth) {
    if (lo == hi) {
        if (depth < m) {
