long long f(int n, int h) {
    if (dp[n][h] != -1) {
        return dp[n][h];
    }

    if (n == 0) {
        return 0;
    }
    if (h == 0) {
        dp[n][h] = f(n, 1);
        return dp[n][h];
    }

    long long ans = 0;
    for (int i = 0; i < n; i++) {
        ans += f(n - i - 1, 0) * f(i, h - 1);
        ans += f(n - i - 1, h - 1) * f(i, 0);
        ans -= f(n - i - 1, h - 1) * f(i, h - 1);
    }

    dp[n][h] = ans;
    return ans;
}

