    int n, h;
    cin >> n >> h;

    // Initialize dp array with -1
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= n; j++) {
            dp[i][j] = -1;
        }
    }

    dp[0][0] = 1;

    cout << f(n, h) << endl;

    return 0;
}

